p.status = 'published' AND p.published_at IS NOT NULL
AND c.slug = #{category}
AND EXISTS ( SELECT 1 FROM post_tag pt JOIN tag t ON t.id = pt.tag_id WHERE pt.post_id = p.id AND t.slug = #{tag} )
AND p.pinned = #{pinned}
AND ( p.title LIKE CONCAT('%', #{q}, '%') OR p.excerpt LIKE CONCAT('%', #{q}, '%') OR p.content LIKE CONCAT('%', #{q}, '%') OR EXISTS ( SELECT 1 FROM post_tag pt JOIN tag t ON t.id = pt.tag_id WHERE pt.post_id = p.id AND t.name LIKE CONCAT('%', #{q}, '%') ) )

